<script setup lang="ts">
import type {Task,Value} from '../types'
import {display} from '../types'
import DependencyGraph from './DependencyGraph.vue'
const props=defineProps<{task:Task;modelValue:Value;locked?:boolean}>()
const emit=defineEmits<{ 'update:modelValue':[Value] }>()
function setRole(id:string,value:string){const current=typeof props.modelValue==='object'&&!Array.isArray(props.modelValue)?props.modelValue:{};emit('update:modelValue',{...current,[id]:value})}
</script>
<template><div class="problem-content"><DependencyGraph v-if="task.family==='dependencies'" :courses="task.render.courses!" :edges="task.render.edges!" :cycle="task.result?.explanation?.witness?.cycle"/>
 <div v-else-if="task.family==='logic'" class="speakers"><div v-for="p in task.render.people" :key="p.id" class="speaker"><span class="speaker-name">{{p.name}} says</span><p>“{{p.statement}}.”</p><fieldset v-if="!locked" class="role-choices"><legend class="sr-only">{{p.name}}’s role</legend><label v-for="role in [{id:'truth',label:'Truth-teller'},{id:'lie',label:'Liar'}]" :key="role.id" class="choice compact" :class="{chosen:(modelValue as Record<string,string>)?.[p.id]===role.id}"><input type="radio" :name="'role-'+p.id" :value="role.id" :checked="(modelValue as Record<string,string>)?.[p.id]===role.id" @change="setRole(p.id,role.id)">{{role.label}}</label></fieldset></div></div>
 <div v-else-if="task.family==='ordering'" class="ordering"><p class="eyebrow">GIVEN CONSTRAINTS</p><table v-if="task.render.presentation==='schedule'" class="schedule-table"><caption class="eyebrow">PROJECT SCHEDULE</caption><thead><tr><th>Task</th><th>Must finish first</th></tr></thead><tbody><tr v-for="row in task.render.schedule_rows" :key="row.task"><td>{{row.task}}</td><td>{{row.prerequisites.length?row.prerequisites.join(', '):'No prerequisite'}}</td></tr></tbody></table><ol v-else class="premises"><li v-for="p in task.render.premises" :key="p">{{p}}</li></ol><div class="claim"><span class="eyebrow">PROPOSED RELATIONSHIP</span><p>{{task.render.claim}}</p></div></div>
 <div v-else class="rules-problem"><div v-if="task.family==='induction'" class="example-table"><table><caption class="eyebrow">OBSERVED EXAMPLES</caption><thead><tr><th>Input</th><th aria-label="maps to"></th><th>Output</th></tr></thead><tbody><tr v-for="(e,i) in task.render.examples" :key="i"><td>{{display(e.input)}}</td><td>→</td><td>{{display(e.output)}}</td></tr><tr class="target"><td>{{display(task.render.target)}}</td><td>→</td><td>?</td></tr></tbody></table></div><div class="candidate-rules"><span class="eyebrow">FINITE CANDIDATE SET</span><p class="micro">The rule is exactly one of these.</p><ol><li v-for="c in task.render.candidates" :key="c.id">{{c.label}}</li></ol></div></div>
 <fieldset v-if="!locked&&task.family==='dependencies'" class="answer-choices"><legend>Your conclusion</legend><label class="choice" :class="{chosen:modelValue===v}" v-for="v in [true,false]" :key="String(v)"><input type="radio" name="completion" :checked="modelValue===v" @change="emit('update:modelValue',v)">{{v?'Yes, every course can be completed':'No, a circular dependency prevents it'}}</label></fieldset>
 <fieldset v-if="!locked&&task.family==='ordering'" class="answer-choices"><legend>Your conclusion</legend><label v-for="v in [{id:'true',label:'Necessarily true',detail:'Holds in every valid order'},{id:'false',label:'Necessarily false',detail:'Holds in no valid order'},{id:'undetermined',label:'Undetermined',detail:'Holds in some valid orders, but not all'}]" :key="v.id" class="choice" :class="{chosen:modelValue===v.id}"><input type="radio" name="ordering-answer" :checked="modelValue===v.id" @change="emit('update:modelValue',v.id)"><span>{{v.label}}<small>{{v.detail}}</small></span></label></fieldset>
 <fieldset v-if="!locked&&task.family==='hypothesis'" class="answer-choices"><legend>Identify the hidden rule</legend><label v-for="c in task.render.candidates" :key="c.id" class="choice" :class="{chosen:modelValue===c.id}"><input type="radio" name="rule" :checked="modelValue===c.id" @change="emit('update:modelValue',c.id)">{{c.label}}</label></fieldset>
 </div></template>
